import { Injectable } from '@angular/core';
import { style as listbox_style } from '@primeuix/styles/listbox';
import { BaseStyle } from 'primeng/base';

const style = /*css*/ `
    ${listbox_style}

    /* For PrimeNG */
    .p-listbox.ng-invalid.ng-dirty {
        border-color: dt('listbox.invalid.border.color');
    }

    .p-listbox-header {
        display: flex;
        align-items: center;
    }

    .p-listbox-header > .p-iconfield {
        flex-grow: 1;
    }

    .p-listbox-list-container {
        height: 100%;
    }

    /* scrollHeight="flex": the root fills its flex-constrained parent and lays out
       as a column so the header/filter keep their natural height and the scrollable
       list shrinks to the remaining space instead of overflowing the container. */
    .p-listbox-flex-scrollable {
        display: flex;
        flex-direction: column;
        height: 100%;
    }

    .p-listbox-flex-scrollable .p-listbox-list-container {
        flex: 1;
    }

    /* CDK Drag & Drop styles */
    /* The single-item ghost and the rows inside the multi-selection preview both
       use the plain list background, so a multi-drag looks like several copies of
       the single-drag ghost rather than a block of highlighted (selected) rows. */
    .p-listbox-option.cdk-drag-preview,
    .p-listbox-drag-preview .p-listbox-option {
        background: dt('listbox.background');
    }

    /* Multi-selection drag preview: dragging an option that is part of a
       multi-selection previews the whole selection. The preview mirrors the
       listbox DOM so the theme styles the rows, but the container card chrome
       (background, border, shadow) is stripped so the floating copy reads as a
       bare silhouette of the dragged rows rather than a detached panel. */
    .p-listbox.p-listbox-drag-preview {
        max-width: 20rem;
        pointer-events: none;
        background: transparent;
        border: 0 none;
        box-shadow: none;
    }

    .p-listbox-drag-preview .p-listbox-list {
        padding: 0;
    }

    .p-listbox-drag-preview-more {
        opacity: 0.7;
    }

    .p-listbox-dragging .p-listbox-option:not(.cdk-drag-preview) {
        pointer-events: none !important;
    }

    .p-listbox-dragging .p-listbox-option:not(.cdk-drag-preview):hover {
        background: inherit !important;
        color: inherit !important;
    }

    .cdk-drag-placeholder {
        pointer-events: none;
    }
`;

const classes = {
    root: ({ instance }) => [
        'p-listbox p-component',
        {
            'p-listbox-striped': instance.striped(),
            'p-disabled': instance.$disabled(),
            'p-invalid': instance.invalid(),
            'p-listbox-fluid': instance.fluid(),
            'p-listbox-dragging': instance.isDragging(),
            'p-listbox-flex-scrollable': instance.scrollHeight() === 'flex'
        }
    ],
    header: 'p-listbox-header',
    pcFilter: 'p-listbox-filter',
    listContainer: 'p-listbox-list-container',
    list: 'p-listbox-list',
    optionGroup: 'p-listbox-option-group',
    option: ({ instance, option, i, scrollerOptions }) => [
        'p-listbox-option',
        {
            'p-listbox-option-selected': instance.isSelected(option) && instance.highlightOnSelect(),
            'p-focus': instance.focusedOptionIndex() === instance.getOptionIndex(i, scrollerOptions),
            'p-disabled': instance.isOptionDisabled(option)
        }
    ],
    optionCheckIcon: 'p-listbox-option-check-icon',
    optionBlankIcon: 'p-listbox-option-blank-icon',
    emptyMessage: 'p-listbox-empty-message',
    // Root + list + option classes mirror the listbox DOM so the theme styles the preview.
    // Options are intentionally NOT marked selected, so the preview rows match the plain
    // single-item drag ghost instead of the highlighted selected background.
    dragPreview: 'p-listbox p-component p-listbox-drag-preview',
    dragPreviewOption: 'p-listbox-option',
    dragPreviewMore: 'p-listbox-option p-listbox-drag-preview-more'
};

@Injectable()
export class ListBoxStyle extends BaseStyle {
    name = 'listbox';

    style = style;

    classes = classes;
}

/**
 *
 * ListBox is used to select one or more values from a list of items.
 *
 * [Live Demo](https://www.primeng.org/listbox/)
 *
 * @module listboxstyle
 *
 */
export enum ListboxClasses {
    /**
     * Class name of the root element
     */
    root = 'p-listbox',
    /**
     * Class name of the header element
     */
    header = 'p-listbox-header',
    /**
     * Class name of the filter element
     */
    pcFilter = 'p-listbox-filter',
    /**
     * Class name of the list container element
     */
    listContainer = 'p-listbox-list-container',
    /**
     * Class name of the list element
     */
    list = 'p-listbox-list',
    /**
     * Class name of the option group element
     */
    optionGroup = 'p-listbox-option-group',
    /**
     * Class name of the option element
     */
    option = 'p-listbox-option',
    /**
     * Class name of the option check icon element
     */
    optionCheckIcon = 'p-listbox-option-check-icon',
    /**
     * Class name of the option blank icon element
     */
    optionBlankIcon = 'p-listbox-option-blank-icon',
    /**
     * Class name of the empty message element
     */
    emptyMessage = 'p-listbox-empty-message',
    /**
     * Class name of the multi-selection drag preview container
     */
    dragPreview = 'p-listbox-drag-preview',
    /**
     * Class name of the overflow row in the multi-selection drag preview
     */
    dragPreviewMore = 'p-listbox-drag-preview-more'
}

export interface ListboxStyle extends BaseStyle {}
